-- fdh-c-check: ip summary of ADP (reads opitemrece: run alone, one statement at a time)
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (6, in order of the placeholders): start, end, sel_json, closed_json, lab_csv, cat_csv
-- returns c_code, fdh_file, n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e),
sel AS (SELECT j.k FROM JSON_TABLE(?, '$[*]' COLUMNS (k BIGINT PATH '$')) j),
cl AS (SELECT j.k FROM JSON_TABLE(?, '$[*]' COLUMNS (k BIGINT PATH '$')) j),
a AS (
  SELECT i.hn AS HN, i.an AS AN, i.vn AS VN, i.pttype AS PTTYPE, i.regdate AS REGDATE, i.dchdate AS DCHDATE,
         DATE_FORMAT(i.regdate, '%Y-%m-%d') AS DATEADM, DATE_FORMAT(i.regtime, '%H%i') AS TIMEADM,
         DATE_FORMAT(i.dchdate, '%Y-%m-%d') AS DATEDSC, DATE_FORMAT(i.dchtime, '%H%i') AS TIMEDSC,
         TIMESTAMP(i.regdate, i.regtime) AS ADM_AT, TIMESTAMP(i.dchdate, i.dchtime) AS DSC_AT,
         COALESCE(i.dchstts, '1') AS DISCHS, COALESCE(i.dchtype, '1') AS DISCHT,
         i.dchstts AS DISCHS_RAW, i.dchtype AS DISCHT_RAW,
         ROUND(COALESCE(i.bw, 0) / 1000, 3) AS ADM_W
  FROM p JOIN ipt i ON i.dchdate BETWEEN p.s AND p.e
),
aw AS (
  SELECT i.hn AS HN, i.an AS AN, DATE_FORMAT(i.regdate, '%Y-%m-%d') AS DATEADM, DATE_FORMAT(i.dchdate, '%Y-%m-%d') AS DATEDSC
  FROM p JOIN ipt i ON i.dchdate BETWEEN (SELECT MIN(m.regdate) FROM ipt m WHERE m.dchdate BETWEEN p.s AND p.e) AND p.e
),
ph AS (SELECT DISTINCT HN FROM a),
cs AS (SELECT HN, AN, '' AS SEQ, AN AS K FROM a),
ins AS (
  SELECT v.hn AS HN, COALESCE(t.hipdata_code, t.pcode, 'UCS') AS INSCL,
         CASE WHEN t.hipdata_code = 'UCS' THEN COALESCE(NULLIF((SELECT MAX(n.nhso_authen_code) FROM nhso_confirm_privilege n WHERE n.vn = a.VN AND n.nhso_status = 'Y' AND n.nhso_authen_code <> ''), ''), NULLIF(ap.auth_code, ''), '')
              WHEN t.hipdata_code IN ('OFC', 'LGO') THEN COALESCE(NULLIF(ap.claim_code, ''), NULLIF(ap.auth_code, ''), '')
              WHEN t.hipdata_code = 'STP' THEN COALESCE(NULLIF(ap.auth_code, ''), '')
              ELSE COALESCE(v.pttypeno, '') END AS PERMITNO,
         a.AN AS AN, v.vn AS SEQ
  FROM a INNER JOIN ovst v ON v.an = a.AN
  INNER JOIN patient pt ON pt.hn = v.hn
  LEFT JOIN pttype t ON t.pttype = v.pttype
  LEFT JOIN patient_pttype pp ON pp.hn = v.hn AND pp.pttype = v.pttype
  LEFT JOIN ipt_pttype ap ON ap.an = a.AN AND ap.pttype = v.pttype
),
dx AS (
  SELECT a.HN, a.AN, '' AS SEQ, a.AN AS K, REPLACE(id.icd10, '.', '') AS DIAG,
         COALESCE(id.diagtype, '1') AS DXTYPE, id.diagtype AS DXTYPE_RAW
  FROM a JOIN iptdiag id ON id.an = a.AN
),
stp AS (
  SELECT DISTINCT v.hn AS HN, a.AN AS AN, '' AS SEQ,
         COALESCE(v.hospmain, (SELECT hospitalcode FROM opdconfig LIMIT 1)) AS HOSPMAIN,
         COALESCE(v.hospsub, v.hospmain, (SELECT hospitalcode FROM opdconfig LIMIT 1)) AS HOSPSUB,
         COALESCE(NULLIF(ap.auth_code, ''), '') AS PERMITNO
  FROM a INNER JOIN ovst v ON v.an = a.AN
  INNER JOIN patient pt ON pt.hn = v.hn
  LEFT JOIN ipt_pttype ap ON ap.an = a.AN AND ap.pttype = v.pttype
  WHERE v.pttype IN (SELECT pttype FROM pttype WHERE hipdata_code = 'STP')
),
dx_s AS (
  SELECT s.HN, s.AN, s.SEQ, id.icd10 AS DIAG, COALESCE(id.diagtype, '1') AS DXTYPE
  FROM stp s JOIN iptdiag id ON id.an = s.AN
),
aer_s AS (
  SELECT s.HN, s.AN, s.SEQ, COALESCE(rin.refer_hospcode, rin.hospcode, '') AS REFMAINI, COALESCE(rout.refer_hospcode, '') AS REFMAINO,
         rin.vn IS NOT NULL AS HAS_IN, rout.vn IS NOT NULL AS HAS_OUT
  FROM stp s INNER JOIN ovst v ON v.an = s.AN INNER JOIN er_regist er ON er.vn = v.vn
  LEFT JOIN referin rin ON rin.vn = er.vn LEFT JOIN referout rout ON rout.vn = er.vn
),
orf_s AS (
  SELECT s.HN, s.AN, s.SEQ, COALESCE(ro.refer_hospcode, ro.hospcode) AS REFER
  FROM stp s JOIN ipt i ON i.an = s.AN JOIN referout ro ON ro.vn = i.vn
),
it AS (
  SELECT op.hn AS HN, op.an AS AN, '' AS SEQ, op.an AS K, DATE_FORMAT(COALESCE(op.rxdate, op.vstdate), '%Y-%m-%d') AS D,
         op.icode AS ICODE, LPAD(COALESCE(inc.drg_chrgitem_id, inc.std_group, op.income), 2, '0') AS CHRGITEM,
         COALESCE(nd.icode IS NOT NULL AND COALESCE(inc.drg_chrgitem_id, 0) NOT IN (3, 4), 0) AS IS_ADP,
         COALESCE(d.icode IS NOT NULL AND inc.drg_chrgitem_id IN (3, 4), 0) AS IS_DRU,
         COALESCE(d.icode IS NOT NULL AND (op.income = '20' OR COALESCE(d.drugaccount, '') IN ('', '-')), 0) AS IS_NED,
         COALESCE(CASE inc.drg_chrgitem_id WHEN 1 THEN 10 WHEN 5 THEN 11 WHEN 13 THEN 12 WHEN 6 THEN 14 WHEN 7 THEN 15 WHEN 8 THEN 16 WHEN 12 THEN 17 WHEN 10 THEN 18 WHEN 11 THEN 19 WHEN 14 THEN 20 END, nd.nhso_adp_type_id, 3) AS ADPTYPE, nd.nhso_adp_code AS ADPCODE, COALESCE(nd.nhso_adp_code, nd.billcode, op.icode) AS CODE,
         op.qty AS QTY, CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END AS SP, CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END AS TOTAL, ROUND(COALESCE(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END, 0) * CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 AND CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END > 0 THEN ROUND(op.sum_price / CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END, 2) ELSE ROUND(op.unitprice, 2) END, 2) AS QXP
  FROM a JOIN opitemrece op FORCE INDEX (ix_an) ON op.an = a.AN
  LEFT JOIN income inc ON inc.income = op.income
  LEFT JOIN nondrugitems nd ON nd.icode = op.icode
  LEFT JOIN drugitems d ON d.icode = op.icode
),
cht AS (
  SELECT ans.hn AS HN, ans.an AS AN, '' AS SEQ, ans.an AS K, ROUND(COALESCE(x.S, 0), 2) AS TOTAL
  FROM a JOIN an_stat ans ON ans.an = a.AN LEFT JOIN (SELECT K, SUM(SP) AS S FROM it GROUP BY K) x ON x.K = ans.an
),
cha AS (
  SELECT HN, AN, SEQ, K, D, CHRGITEM, ROUND(SUM(SP), 2) AS AMOUNT FROM it
  GROUP BY HN, AN, SEQ, K, D, CHRGITEM HAVING ROUND(SUM(SP), 2) > 0
),
cmp AS (
  SELECT HN, AN, SEQ, K, CHRGITEM,
         SUM(CASE WHEN AMT > 0 THEN AMT END) AS A,
         CASE WHEN SUM(ITN) > 0 THEN ROUND(SUM(ITM), 2) END AS T
  FROM (SELECT HN, AN, SEQ, K, D, CHRGITEM, ROUND(SUM(SP), 2) AS AMT, SUM(IS_ADP OR IS_DRU) AS ITN,
               SUM(CASE WHEN IS_ADP OR IS_DRU THEN QXP END) AS ITM
        FROM it GROUP BY HN, AN, SEQ, K, D, CHRGITEM) g
  GROUP BY HN, AN, SEQ, K, CHRGITEM HAVING SUM(AMT > 0) > 0
),
adp_s AS (
  SELECT s.HN, s.AN, s.SEQ, DATE_FORMAT(COALESCE(op.rxdate, op.vstdate), '%Y-%m-%d') AS DATEOPD, COALESCE(CASE inc.drg_chrgitem_id WHEN 1 THEN 10 WHEN 5 THEN 11 WHEN 13 THEN 12 WHEN 6 THEN 14 WHEN 7 THEN 15 WHEN 8 THEN 16 WHEN 12 THEN 17 WHEN 10 THEN 18 WHEN 11 THEN 19 WHEN 14 THEN 20 END, nd.nhso_adp_type_id, 3) AS ADPTYPE, COALESCE(nd.nhso_adp_code, nd.billcode, op.icode) AS CODE,
         ROUND(op.qty, 2) AS QTY, CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 AND CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END > 0 THEN ROUND(op.sum_price / CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END, 2) ELSE ROUND(op.unitprice, 2) END AS RATE, CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END AS TOTAL
  FROM stp s JOIN opitemrece op ON op.an = s.AN INNER JOIN nondrugitems nd ON nd.icode = op.icode LEFT JOIN income inc ON inc.income = op.income
  WHERE COALESCE(inc.drg_chrgitem_id, 0) NOT IN (3, 4)
),
dru_s AS (
  SELECT s.HN, s.AN, s.SEQ, ROUND(op.qty, 0) AS AMOUNT, CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 AND CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END > 0 THEN ROUND(op.sum_price / CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END, 2) ELSE ROUND(op.unitprice, 2) END AS DRUGPRICE, CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END AS TOTAL,
         CASE WHEN op.item_type = 'H' OR op.income = '04' THEN '2' ELSE '1' END AS USE_STATUS
  FROM stp s JOIN opitemrece op ON op.an = s.AN INNER JOIN income inc ON inc.income = op.income AND inc.drg_chrgitem_id IN (3, 4) INNER JOIN drugitems d ON d.icode = op.icode
),
cha_s AS (
  SELECT s.HN, s.AN, s.SEQ, COALESCE(op.rxdate, op.vstdate) AS D,
         LPAD(COALESCE(inc.drg_chrgitem_id, inc.std_group, op.income), 2, '0') AS CHRGITEM, ROUND(SUM(CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END), 2) AS AMOUNT
  FROM stp s JOIN opitemrece op ON op.an = s.AN LEFT JOIN income inc ON inc.income = op.income
  GROUP BY s.HN, s.AN, s.SEQ, COALESCE(op.rxdate, op.vstdate), LPAD(COALESCE(inc.drg_chrgitem_id, inc.std_group, op.income), 2, '0')
  HAVING ROUND(SUM(CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END), 2) > 0
),
cht_s AS (
  SELECT s.HN, s.AN, s.SEQ, ROUND(COALESCE((SELECT SUM(CASE WHEN ABS(COALESCE(op.sum_price, 0) - COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0)) >= 1 THEN ROUND(op.sum_price, 2) ELSE COALESCE(ROUND(CASE WHEN inc.drg_chrgitem_id IN (3, 4) THEN ROUND(op.qty, 0) ELSE ROUND(op.qty, 2) END * ROUND(op.unitprice, 2), 2), 0) END) FROM opitemrece op FORCE INDEX (ix_an) LEFT JOIN income inc ON inc.income = op.income WHERE op.an = s.AN), 0), 2) AS TOTAL FROM stp s
)
SELECT c_code, fdh_file, COUNT(*) AS n FROM (
SELECT '301' AS c_code, 'ADP' AS fdh_file, HN AS hn, AN AS an, SEQ AS seq, CONCAT(CODE, ' ', TOTAL) AS found FROM it WHERE IS_ADP AND TOTAL < 0
UNION ALL SELECT '312', 'ADP', x.HN, x.AN, '', CONCAT(x.CODE, ' ', x.Q, ' > ', l.LOS)
  FROM (SELECT HN, AN, CODE, SUM(QTY) AS Q FROM it WHERE IS_ADP AND ADPTYPE = 10 GROUP BY HN, AN, CODE) x
  JOIN (SELECT a.AN, GREATEST(DATEDIFF(a.DCHDATE, a.REGDATE), 1) - COALESCE(SUM(DATEDIFF(hl.reg_date, hl.dch_date)), 0) AS LOS
        FROM a LEFT JOIN ipt_home_leave hl ON hl.an = a.AN GROUP BY a.AN, a.DCHDATE, a.REGDATE) l ON l.AN = x.AN
  WHERE x.Q > l.LOS + 1
UNION ALL SELECT '952', 'ADP', HN, AN, SEQ, CONCAT(CHRGITEM, ' ', COUNT(*)) FROM it WHERE IS_ADP GROUP BY HN, AN, SEQ, CHRGITEM HAVING COUNT(*) > 999
UNION ALL SELECT c.c, 'ADP', x.HN, x.AN, '', CASE c.c WHEN '914' THEN x.LAB WHEN '190' THEN x.CAT ELSE x.NOC END
  FROM (SELECT HN, AN,
         GROUP_CONCAT(DISTINCT CASE WHEN CHRGITEM = '07' AND NOT FIND_IN_SET(ICODE, ?) THEN ICODE END ORDER BY ICODE) AS LAB,
         GROUP_CONCAT(DISTINCT CASE WHEN CHRGITEM = '07' AND NOT FIND_IN_SET(ICODE, ?) THEN ICODE END ORDER BY ICODE) AS CAT,
         GROUP_CONCAT(DISTINCT CASE WHEN TRIM(COALESCE(ADPCODE, '')) = '' THEN ICODE END ORDER BY ICODE) AS NOC
        FROM it WHERE IS_ADP AND CHRGITEM IN ('06', '07') GROUP BY HN, AN) x
  JOIN (SELECT '914' AS c UNION ALL SELECT '190' UNION ALL SELECT '309') c
  WHERE (c.c = '914' AND x.LAB IS NOT NULL) OR (c.c = '190' AND x.CAT IS NOT NULL) OR (c.c = '309' AND x.NOC IS NOT NULL)
UNION ALL SELECT 'STP-R108' AS c_code, 'ADP' AS fdh_file, HN AS hn, AN AS an, SEQ AS seq, CONCAT_WS('/', QTY, RATE, TOTAL) AS found FROM adp_s WHERE QTY IS NULL OR QTY <= 0 OR RATE IS NULL OR RATE <= 0 OR TOTAL IS NULL OR TOTAL <= 0
UNION ALL SELECT 'STP-R188', 'ADP', HN, AN, SEQ, CODE FROM adp_s WHERE CODE NOT IN ('55999', '57999') GROUP BY HN, AN, SEQ, DATEOPD, ADPTYPE, CODE HAVING COUNT(*) > 1
UNION ALL SELECT 'STP-R292', 'ADP', HN, AN, SEQ, QTY FROM adp_s WHERE CODE = 'S1801' AND (QTY < 1 OR QTY > 2)
UNION ALL SELECT 'STP-R180', 'ADP', x.HN, x.AN, x.SEQ, x.CODE FROM adp_s x WHERE x.CODE = 'S1802' AND NOT EXISTS (SELECT 1 FROM adp_s y WHERE y.CODE = 'S1801' AND y.AN = x.AN AND y.SEQ = x.SEQ) GROUP BY x.HN, x.AN, x.SEQ, x.CODE
UNION ALL SELECT 'STP-R194', 'ADP', HN, AN, SEQ, COUNT(*) FROM adp_s WHERE CODE = 'S1801' GROUP BY HN, AN, SEQ HAVING COUNT(*) > 1
) r GROUP BY c_code, fdh_file;
